mapper.select:
SELECT *
  FROM batch.alert_escalation_notification_outbox
 WHERE publish_status IN (#{pendingStatus1}, #{pendingStatus2})
   AND next_publish_at <= #{now}
 ORDER BY next_publish_at ASC, id ASC
 LIMIT #{limit}

SELECT *
  FROM batch.alert_escalation_notification_outbox
 WHERE publish_status = #{publishingStatus}
   AND updated_at < CURRENT_TIMESTAMP - (#{timeoutSeconds} * interval '1 second')
 ORDER BY updated_at ASC, id ASC
 LIMIT #{limit}

mapper.update:
UPDATE batch.alert_escalation_notification_outbox
   SET publish_status = #{publishingStatus},
       updated_at     = CURRENT_TIMESTAMP
 WHERE id = #{id}
   AND tenant_id = #{tenantId}
   AND publish_status IN (#{pendingStatus1}, #{pendingStatus2})

UPDATE batch.alert_escalation_notification_outbox
   SET publish_status = #{publishedStatus},
       updated_at     = CURRENT_TIMESTAMP
 WHERE id = #{id}
   AND tenant_id = #{tenantId}
   AND publish_status = #{publishingStatus}

UPDATE batch.alert_escalation_notification_outbox
   SET publish_status   = #{failedStatus},
       attempt_count    = attempt_count + 1,
       next_publish_at  = #{nextPublishAt},
       last_error       = #{lastError,jdbcType=VARCHAR},
       updated_at       = CURRENT_TIMESTAMP
 WHERE id = #{id}
   AND tenant_id = #{tenantId}
   AND publish_status = #{publishingStatus}

UPDATE batch.alert_escalation_notification_outbox
   SET publish_status = #{giveUpStatus},
       attempt_count  = attempt_count + 1,
       last_error     = #{lastError,jdbcType=VARCHAR},
       updated_at     = CURRENT_TIMESTAMP
 WHERE id = #{id}
   AND tenant_id = #{tenantId}
   AND publish_status = #{publishingStatus}

UPDATE batch.alert_escalation_notification_outbox
   SET publish_status  = #{failedStatus},
       last_error      = 'stale publishing reset',
       next_publish_at = CURRENT_TIMESTAMP,
       updated_at      = CURRENT_TIMESTAMP
 WHERE id = #{id}
   AND tenant_id = #{tenantId}
   AND publish_status = #{publishingStatus}
